    override func viewDidLoad() {
        super.viewDidLoad(); title = "Store"
        let layout = UICollectionViewFlowLayout(); layout.minimumLineSpacing = 10; layout.minimumInteritemSpacing = 9; layout.sectionInset = UIEdgeInsets(top: 4, left: 12, bottom: 105, right: 12); layout.headerReferenceSize = CGSize(width: view.bounds.width, height: 245)
