    func collectionView(_ collectionView: UICollectionView, layout collectionViewLayout: UICollectionViewLayout, sizeForItemAt indexPath: IndexPath) -> CGSize { CGSize(width: (collectionView.bounds.width - 42) / 3, height: 160) }
    func collectionView(_ collectionView: UICollectionView, didSelectItemAt indexPath: IndexPath) { let item = items[indexPath.item]; if LookMeExperienceStore.shared.buy(id: item.id, name: item.name, symbol: item.symbol, price: item.price) { CoinPrompt.spent(from: self, amount: item.price, activity: "\(item.name) was added to your Backpack") } else { CoinPrompt.insufficient(from: self, required: item.price, activity: item.name) { [weak self] in self?.navigationController?.pushViewController(CoinVaultViewController(), animated: true) } } }
    func collectionView(_ collectionView: UICollectionView, viewForSupplementaryElementOfKind kind: String, at indexPath: IndexPath) -> UICollectionReusableView { let header = collectionView.dequeueReusableSupplementaryView(ofKind: kind, withReuseIdentifier: "storeHeader", for: indexPath) as! EffectCatalogHeader; header.configure(selected: category) { [weak self] value in self?.category = value; self?.collectionView.reloadData() }; return header }
    private func refreshBalance() { balance.text = LookMeExperienceStore.shared.coins.formatted() }
    @objc private func rechargeTapped() { navigationController?.pushViewController(CoinVaultViewController(), animated: true) }
    private func toast(_ message: String) { let a = UIAlertController(title: message, message: nil, preferredStyle: .alert); present(a, animated: true); DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) { a.dismiss(animated: true) } }
}

