final class BackpackViewController: LMViewController, UICollectionViewDataSource, UICollectionViewDelegateFlowLayout {
    private var collectionView: UICollectionView!
    override func viewDidLoad() { super.viewDidLoad(); title = "Backpack"; let layout = UICollectionViewFlowLayout(); layout.minimumLineSpacing = 12; layout.minimumInteritemSpacing = 10; layout.sectionInset = UIEdgeInsets(top: 18, left: 14, bottom: 20, right: 14); collectionView = UICollectionView(frame: .zero, collectionViewLayout: layout); collectionView.backgroundColor = .clear; collectionView.dataSource = self; collectionView.delegate = self; collectionView.register(CollectedEffectCell.self, forCellWithReuseIdentifier: "bag"); view.addSubview(collectionView); collectionView.pin(to: view) }
    func collectionView(_ collectionView: UICollectionView, numberOfItemsInSection section: Int) -> Int { max(1, LookMeExperienceStore.shared.backpack.count) }
    func collectionView(_ collectionView: UICollectionView, cellForItemAt indexPath: IndexPath) -> UICollectionViewCell { let cell = collectionView.dequeueReusableCell(withReuseIdentifier: "bag", for: indexPath) as! CollectedEffectCell; if LookMeExperienceStore.shared.backpack.isEmpty { cell.configureEmpty() } else { cell.configure(LookMeExperienceStore.shared.backpack[indexPath.item]) }; return cell }
    func collectionView(_ collectionView: UICollectionView, layout collectionViewLayout: UICollectionViewLayout, sizeForItemAt indexPath: IndexPath) -> CGSize { LookMeExperienceStore.shared.backpack.isEmpty ? CGSize(width: collectionView.bounds.width - 28, height: 210) : CGSize(width: (collectionView.bounds.width - 38) / 2, height: 170) }
}

